{"version":3,"file":"exec-app.jsdbx","sources":["../../src/client/components/exec/ExecHeader.tsx","../../src/client/exec-app.css","../../src/client/components/exec/ExecHeader.css","../../src/client/components/exec/ExecImpactBar.css","../../src/client/components/exec/ExecImpactBar.tsx","../../src/client/components/exec/ExecHealthScore.tsx","../../src/client/components/exec/ExecHealthScore.css","../../src/client/components/exec/ExecContributors.css","../../src/client/components/exec/ExecContributors.tsx","../../src/client/components/exec/ExecKpiGrid.css","../../src/client/components/exec/ExecKpiGrid.tsx","../../src/client/components/exec/ExecCityLeaderboard.css","../../src/client/components/exec/ExecCityLeaderboard.tsx","../../src/client/components/exec/ExecRegionalMap.css","../../src/client/components/exec/ExecRegionalMap.tsx","../../src/client/components/exec/ExecGrowthChart.tsx","../../src/client/components/exec/ExecGrowthChart.css","../../src/client/components/exec/ExecAiInsights.css","../../src/client/components/exec/ExecAiInsights.tsx","../../src/client/components/exec/ExecFinancial.css","../../src/client/components/exec/ExecFinancial.tsx","../../src/client/components/exec/ExecCustomerExp.css","../../src/client/components/exec/ExecCustomerExp.tsx","../../src/client/components/exec/ExecOperational.css","../../src/client/components/exec/ExecOperational.tsx","../../src/client/components/exec/ExecAiAutomation.css","../../src/client/components/exec/ExecAiAutomation.tsx","../../src/client/components/exec/ExecStoreDistribution.css","../../src/client/components/exec/ExecStoreDistribution.tsx","../../src/client/components/exec/ExecInventory.css","../../src/client/components/exec/ExecInventory.tsx","../../src/client/components/exec/ExecEmployeeProductivity.css","../../src/client/components/exec/ExecEmployeeProductivity.tsx","../../src/client/components/exec/ExecPartnerPerformance.css","../../src/client/components/exec/ExecPartnerPerformance.tsx","../../src/client/components/exec/ExecRiskBoard.css","../../src/client/components/exec/ExecRiskBoard.tsx","../../src/client/components/exec/ExecMarketShare.css","../../src/client/components/exec/ExecMarketShare.tsx","../../src/client/components/exec/ExecPredictive.css","../../src/client/components/exec/ExecPredictive.tsx","../../src/client/components/exec/ExecBoardRecommendations.css","../../src/client/components/exec/ExecBoardRecommendations.tsx","../../src/client/components/exec/ExecTimeline.css","../../src/client/components/exec/ExecTimeline.tsx","../../src/client/components/exec/ExecFooter.css","../../src/client/components/exec/ExecFooter.tsx","../../src/client/exec-app.tsx"],"sourcesContent":["import React from 'react';
import './ExecHeader.css';

export default function ExecHeader() {
  const now = new Date();
  const time = now.toLocaleTimeString('en-IN', { hour: '2-digit', minute: '2-digit' });
  const date = now.toLocaleDateString('en-IN', { weekday: 'short', day: 'numeric', month: 'short', year: 'numeric' });

  return (
    <div className="exec-card exec-header">
      <div className="exec-header__left">
        <h1>Executive Analytics Center</h1>
        <p>Enterprise Performance &amp; Strategic Business Intelligence</p>
      </div>
      <div className="exec-header__right">
        <div className="exec-header__live">
          <span className="exec-header__live-dot"></span>
          LIVE
        </div>
        <div className="exec-header__meta">
          <span>{time}</span>
          <span>{date}</span>
        </div>
        <div className="exec-header__stat">
          <span className="exec-header__stat-icon">🏙️</span>
          15 Cities
        </div>
        <div className="exec-header__stat">
          <span className="exec-header__stat-icon">🏬</span>
          200 Dark Stores
        </div>
      </div>
    </div>
  );
}
","/* ─── Executive Analytics Center - Global Styles ──────────────────────────── */

@keyframes exec-fade-in {
  from { opacity: 0; transform: translateY(12px); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes exec-pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.4; }
}

@keyframes exec-gauge-fill {
  from { stroke-dashoffset: 283; }
}

@keyframes exec-shimmer {
  0% { background-position: -200% 0; }
  100% { background-position: 200% 0; }
}

:root {
  --exec-bg: #0a0e1a;
  --exec-card-bg: #131a2e;
  --exec-card-border: #1e2a45;
  --exec-card-radius: 14px;
  --exec-card-shadow: 0 0 20px rgba(0, 200, 150, 0.08), inset 0 1px 0 rgba(255, 255, 255, 0.03);
  --exec-text-primary: #e2e8f0;
  --exec-text-secondary: #94a3b8;
  --exec-teal: #00c896;
  --exec-blue: #3b82f6;
  --exec-purple: #8b5cf6;
  --exec-orange: #f59e0b;
  --exec-red: #ef4444;
  --exec-font: system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  background: var(--exec-bg);
  color: var(--exec-text-primary);
  font-family: var(--exec-font);
  min-height: 100vh;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

.exec-container {
  max-width: 1600px;
  margin: 0 auto;
  padding: 24px;
  display: flex;
  flex-direction: column;
  gap: 24px;
}

.exec-card {
  background: var(--exec-card-bg);
  border: 1px solid var(--exec-card-border);
  border-radius: var(--exec-card-radius);
  box-shadow: var(--exec-card-shadow);
  padding: 24px;
  animation: exec-fade-in 0.6s ease-out both;
}

.exec-row {
  display: grid;
  gap: 24px;
}

.exec-row--2col {
  grid-template-columns: 1fr 1fr;
}

.exec-section-title {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 1.5px;
  text-transform: uppercase;
  color: var(--exec-text-secondary);
  margin-bottom: 16px;
}

.exec-badge {
  display: inline-flex;
  align-items: center;
  padding: 4px 12px;
  border-radius: 20px;
  font-size: 11px;
  font-weight: 600;
}

.exec-badge--teal {
  background: rgba(0, 200, 150, 0.12);
  color: var(--exec-teal);
}

.exec-badge--blue {
  background: rgba(59, 130, 246, 0.12);
  color: var(--exec-blue);
}

.exec-badge--purple {
  background: rgba(139, 92, 246, 0.12);
  color: var(--exec-purple);
}

.exec-badge--orange {
  background: rgba(245, 158, 11, 0.12);
  color: var(--exec-orange);
}

.exec-badge--red {
  background: rgba(239, 68, 68, 0.12);
  color: var(--exec-red);
}

.exec-progress-bar {
  height: 6px;
  border-radius: 3px;
  background: rgba(255, 255, 255, 0.06);
  overflow: hidden;
}

.exec-progress-bar__fill {
  height: 100%;
  border-radius: 3px;
  transition: width 1.2s cubic-bezier(0.4, 0, 0.2, 1);
}

.exec-live-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--exec-teal);
  animation: exec-pulse 2s ease-in-out infinite;
}

.exec-trend-up {
  color: var(--exec-teal);
}

.exec-trend-down {
  color: var(--exec-red);
}

@media (max-width: 1024px) {
  .exec-row--2col {
    grid-template-columns: 1fr;
  }
}
