}
","import React from 'react';
import './ExecImpactBar.css';

const metrics = [
  { label: "Today's Revenue", value: '₹8.2 Cr', highlight: true },
  { label: 'Profit Saved', value: '₹42 L', highlight: false },
  { label: 'Orders Completed', value: '1,52,000', highlight: false },
  { label: 'AI Decisions', value: '94%', highlight: true },
  { label: 'Customer Satisfaction', value: '96%', highlight: false },
  { label: 'PulseScore', value: '92', highlight: true },
];

export default function ExecImpactBar() {
  return (
    <div className="exec-card exec-impact-bar">
      {metrics.map((m) => (
        <div key={m.label} className="exec-impact-bar__item">
          <span className={`exec-impact-bar__value${m.highlight ? ' exec-impact-bar__value--teal' : ''}`}>
            {m.value}
          </span>
          <span className="exec-impact-bar__label">{m.label}</span>
        </div>
      ))}
    </div>
  );
}
","import React from 'react';
import './ExecHealthScore.css';

export default function ExecHealthScore() {
  const score = 92;
  const circumference = 2 * Math.PI * 45;
  const offset = circumference - (score / 100) * circumference;

  const summaryPoints = [
    'Revenue growth accelerating — up 18% WoW across all regions',
    'AI automation now handling 94% of routine decisions autonomously',
    'Customer satisfaction at all-time high of 96% driven by faster delivery',
    'South region leading expansion with 3 new stores this week',
    'Inventory accuracy improved to 98% reducing wastage by ₹3.2L daily',
  ];

  return (
    <div className="exec-card exec-health-score">
      <div className="exec-section-title">Enterprise PulseScore</div>
      <div className="exec-health-score__gauge">
        <svg width="180" height="180" viewBox="0 0 100 100">
          <circle className="exec-health-score__gauge-bg" cx="50" cy="50" r="45" />
          <circle
            className="exec-health-score__gauge-fill"
            cx="50" cy="50" r="45"
            strokeDasharray={circumference}
            strokeDashoffset={offset}
          />
        </svg>
        <div className="exec-health-score__gauge-text">
          <div className="exec-health-score__score">{score}</div>
          <div className="exec-health-score__label">PulseScore</div>
        </div>
      </div>
      <div className="exec-health-score__status">
        <span className="exec-health-score__status-text">✦ Excellent</span>
      </div>
      <div className="exec-health-score__improvement">
        ↑ +5 improvement this week
      </div>
      <div className="exec-health-score__summary">
        <div className="exec-health-score__summary-title">AI Executive Summary</div>
        <ul className="exec-health-score__summary-list">
          {summaryPoints.map((point, i) => (
            <li key={i} className="exec-health-score__summary-item">{point}</li>
          ))}
        </ul>
      </div>
    </div>
  );
}
