","import React from 'react';
import './ExecContributors.css';

const contributors = [
  { label: 'Revenue Growth', value: 94, color: '#00c896' },
  { label: 'Operations Efficiency', value: 96, color: '#3b82f6' },
  { label: 'Inventory Health', value: 91, color: '#8b5cf6' },
  { label: 'Customer Satisfaction', value: 96, color: '#00c896' },
  { label: 'Employee Productivity', value: 93, color: '#f59e0b' },
  { label: 'Refund Accuracy', value: 97, color: '#3b82f6' },
  { label: 'Partner Performance', value: 92, color: '#8b5cf6' },
  { label: 'AI Automation', value: 95, color: '#00c896' },
];

export default function ExecContributors() {
  return (
    <div className="exec-card exec-contributors">
      <div className="exec-section-title">PulseScore Contributors</div>
      <div className="exec-contributors__list">
        {contributors.map((c) => (
          <div key={c.label} className="exec-contributors__item">
            <span className="exec-contributors__label">{c.label}</span>
            <div className="exec-contributors__bar">
              <div
                className="exec-contributors__bar-fill"
                style={{ width: `${c.value}%`, background: c.color }}
              />
            </div>
            <span className="exec-contributors__value">{c.value}%</span>
          </div>
        ))}
      </div>
    </div>
  );
}
