import './ExecKpiGrid.css';

const kpis = [
  { label: 'Revenue', value: '₹8.2 Cr', trend: '+12%', change: '+₹88L vs yesterday', color: '#00c896', points: '0,25 15,20 30,22 45,15 60,18 75,10 90,12 105,5 120,8' },
  { label: 'Profit', value: '₹2.4 Cr', trend: '+8%', change: '+₹18L vs yesterday', color: '#3b82f6', points: '0,22 15,20 30,18 45,19 60,15 75,12 90,14 105,10 120,8' },
  { label: 'Operating Margin', value: '29%', trend: '+2.1%', change: '+0.8% vs last week', color: '#8b5cf6', points: '0,24 15,22 30,20 45,21 60,18 75,16 90,15 105,14 120,12' },
  { label: 'Avg Delivery', value: '8.1 min', trend: '-0.4', change: 'Fastest this quarter', color: '#00c896', points: '0,10 15,12 30,14 45,12 60,15 75,13 90,18 105,16 120,20' },
  { label: 'Customer NPS', value: '74', trend: '+6', change: '+3 pts this month', color: '#f59e0b', points: '0,26 15,24 30,22 45,20 60,18 75,15 90,12 105,10 120,8' },
  { label: 'Growth', value: '+18%', trend: '↑', change: 'Highest in 6 months', color: '#00c896', points: '0,28 15,25 30,22 45,20 60,16 75,14 90,10 105,8 120,5' },
];

export default function ExecKpiGrid() {
  return (
    <div className="exec-card exec-kpi-grid">
      <div className="exec-section-title">Key Performance Indicators</div>
      <div className="exec-kpi-grid__cards">
        {kpis.map((kpi) => (
          <div key={kpi.label} className="exec-kpi-grid__card">
            <div className="exec-kpi-grid__card-header">
              <span className="exec-kpi-grid__card-label">{kpi.label}</span>
              <span className="exec-kpi-grid__card-trend exec-trend-up">{kpi.trend}</span>
            </div>
            <div className="exec-kpi-grid__card-value">{kpi.value}</div>
            <div className="exec-kpi-grid__card-change">{kpi.change}</div>
            <svg className="exec-kpi-grid__card-sparkline" viewBox="0 0 120 30" preserveAspectRatio="none">
              <polyline points={kpi.points} stroke={kpi.color} />
            </svg>
          </div>
        ))}
      </div>
    </div>
  );
}
