","import React from 'react';
import './ExecStoreDistribution.css';

const stores = [
  { label: 'Healthy', count: 184, color: '#00c896', pct: 92 },
  { label: 'Warning', count: 12, color: '#f59e0b', pct: 6 },
  { label: 'Critical', count: 4, color: '#ef4444', pct: 2 },
];

export default function ExecStoreDistribution() {
  const radius = 45;
  const circumference = 2 * Math.PI * radius;
  let offset = 0;

  return (
    <div className="exec-card exec-store-distribution">
      <div className="exec-section-title">Store Health Distribution</div>
      <div className="exec-store-distribution__content">
        <div className="exec-store-distribution__donut">
          <svg width="140" height="140" viewBox="0 0 100 100">
            {stores.map((s) => {
              const dash = (s.pct / 100) * circumference;
              const currentOffset = offset;
              offset += dash;
              return (
                <circle
                  key={s.label}
                  cx="50" cy="50" r={radius}
                  fill="none"
                  stroke={s.color}
                  strokeWidth="10"
                  strokeDasharray={`${dash} ${circumference - dash}`}
                  strokeDashoffset={-currentOffset}
                  transform="rotate(-90 50 50)"
                />
              );
            })}
          </svg>
          <div className="exec-store-distribution__donut-center">
            <div className="exec-store-distribution__donut-total">200</div>
            <div className="exec-store-distribution__donut-label">Stores</div>
          </div>
        </div>
        <div className="exec-store-distribution__legend">
          {stores.map((s) => (
            <div key={s.label} className="exec-store-distribution__legend-item">
              <span className="exec-store-distribution__legend-dot" style={{ background: s.color }}></span>
              <div className="exec-store-distribution__legend-info">
                <span className="exec-store-distribution__legend-label">{s.label}</span>
                <span className="exec-store-distribution__legend-value">{s.count}</span>
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}
